correct_variants:
int factorial(int n) {
    if (n <= 1) {
        return 1;
    }
    return n * factorial(n - 1);
}

int factorial(int n) {
    if (n == 0) return 1;
    return n * factorial(n - 1);
}

int factorial(int n) {
    int rest;
    if (n < 2) {
        return 1;
    }
    rest = factorial(n - 1);
    return rest * n;
}
